/* Verified PlayCricket performances; independent of fixture announcement artwork. */
export function teamWeekGrade(value,layout={}){return graphicGrade(value,layout,true);}
export function teamWeekFigures(player,display=player.display){
 const batting=(player.batting||[]).map(b=>`${b.runs}${b.not_out?'*':''}`).join(' & ');
 const bowling=(player.bowling||[]).map(b=>`${b.wickets}/${b.runs}`).join(' & ');
 return display==='batting'?batting:display==='bowling'?bowling:[batting,bowling].filter(Boolean).join(' & ');
}
export function teamWeekDisplay(p){return p.wickets>0?(p.runs>=20&&p.batting?.length?'both':'bowling'):p.batting?.length?'batting':p.bowling?.length?'bowling':'batting';}
export function teamWeekOrder(rows){
 const category=p=>p.display==='batting'?0:p.display==='both'?1:2;
 return [...rows].sort((a,b)=>category(a)-category(b)||(category(a)===2?b.wickets-a.wickets||a.conceded-b.conceded:b.runs-a.runs||b.wickets-a.wickets)||a.key.localeCompare(b.key));
}
export function teamWeekWorthwhile(p){return p.runs>=25||p.wickets>=2||(p.runs>=20&&p.wickets>=1);}
export function teamWeekDraft(candidates){
 // Use the best performances, without reserving places for any role.
 const ranked=teamWeekRank(candidates).filter(teamWeekWorthwhile),seen=new Set(),chosen=[];
 for(const p of ranked){if(seen.has(p.player_id))continue;seen.add(p.player_id);chosen.push({...p,display:teamWeekDisplay(p)});if(chosen.length===11)break;}
 return teamWeekOrder(chosen);
}
export function teamWeekRecommendations(candidates,example=[]){
 const seen=new Set(),ranked=teamWeekRank(candidates).filter(p=>{if(seen.has(p.player_id))return false;seen.add(p.player_id);return true;});
 const worthy=ranked.filter(teamWeekWorthwhile),leading=worthy.slice(0,11),cutoff=leading.at(-1)?.points||0;
 const margin=points=>Math.max(8,points*.12);
 const close=leading.length===11?worthy.slice(11).filter(p=>cutoff-p.points<=margin(cutoff)):[];
 // Usually 11–15 names. Keep genuine ties at the boundary for a human decision.
 const alternatives=close.slice(0,4),last=alternatives.at(-1);
 if(last)alternatives.push(...close.slice(4).filter(p=>p.points===last.points));
 const contenders=[...leading,...alternatives],outsideBest=alternatives[0]?.points;
 const strong=teamWeekOrder(leading.filter(p=>outsideBest===undefined||p.points-outsideBest>margin(p.points)).map(p=>({...p,display:teamWeekDisplay(p)})));
 const sure=new Set(strong.map(p=>p.player_id)),shortlist=alternatives.length?contenders.filter(p=>!sure.has(p.player_id)):[];
 const preferred=new Set(example.map(p=>p.player_id));
 // An example helps decide close calls; it cannot hide them or force in weaker performances.
 const choices=[...shortlist].sort((a,b)=>Number(preferred.has(b.player_id))-Number(preferred.has(a.player_id))||a.rank-b.rank);
 const proposed=teamWeekOrder([...strong,...choices.slice(0,11-strong.length).map(p=>({...p,display:teamWeekDisplay(p)}))]);
 return {proposed,strong,shortlist,contenders,clear:proposed.length===11&&!shortlist.length,qualifying:worthy.length};
}
export function teamWeekRank(candidates,mode='overall'){
 const leadingRuns=Math.max(50,...candidates.map(p=>p.runs)),leadingWickets=Math.max(3,...candidates.map(p=>p.wickets));
 const points=p=>{const batting=100*p.runs/leadingRuns,bowling=100*p.wickets/leadingWickets;return Math.round((Math.max(batting,bowling)+(p.runs>=20&&p.wickets>=2?.4*Math.min(batting,bowling):0))*10)/10;};
 const overall=(a,b)=>points(b)-points(a)||b.wickets-a.wickets||a.conceded-b.conceded||b.runs-a.runs||a.key.localeCompare(b.key);
 const sorted=[...candidates].filter(p=>mode==='batting'?p.batting.length:mode==='bowling'?p.bowling.length>0:mode==='allround'?p.runs>=20&&p.wickets>=2:true).sort((a,b)=>mode==='batting'?b.runs-a.runs||overall(a,b):mode==='bowling'?b.wickets-a.wickets||a.conceded-b.conceded||overall(a,b):overall(a,b));
 return sorted.map((p,i)=>({...p,rank:i+1,points:points(p),reason:[p.runs?`${p.runs} runs`:'',p.wickets?`${p.wickets} wicket${p.wickets===1?'':'s'}`:'',p.runs>=20&&p.wickets>=2?'all-round bonus':''].filter(Boolean).join(' · ')||'No runs or wickets'}));
}
export function teamWeekMatchExample(candidates,reference,layout={}){
 const normal=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const grade=v=>normal(teamWeekGrade(v,layout)),matched=[],unmatched=[],used=new Set();
 for(const row of reference?.names||[]){
  const eligible=candidates.filter(p=>!used.has(p.player_id)&&(!row.grade||grade(p.grade)===grade(row.grade)));
  const override=reference.matches?.[row.name];
  const exact=eligible.filter(p=>override?p.player_id===override:normal(p.name)===normal(row.name));
  if(exact.length===1){matched.push({...exact[0],reference_figures:row.figures||''});used.add(exact[0].player_id);}
  else unmatched.push({...row,options:eligible.filter(p=>normal(p.name.split(' ').at(-1))===normal(row.name.split(' ').at(-1)))});
 }
 return {matched,unmatched};
}
